import re
d="/home/claude/three-bases/library/tools/key/shadowverse/"
for name,b in [("covsettle_00",b0),("covsettle_01",b1)]:
    ids=[l.split(" | ")[0] for l in open(d+name+".txt") if re.match(r"^\d",l)]
    txt={l.split(" | ")[0]:l for l in open(d+name+".txt") if re.match(r"^\d",l)}
    assert set(ids)==set(b),(name,set(ids)^set(b))
